)

var globalHistoryResourceAdmission = newHistoryResourceAdmission(8)

func acquireHistoryHeavyBudget(ctx context.Context, userID string, vehicleID int) (func(), error) {
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	return globalHistoryResourceAdmission.acquire(ctx, userID+"\x00"+strconv.Itoa(vehicleID))
}

