package main

import (
	"context"
	"testing
)

func TestHistoryHeavyBudgetCancellationAndTenantKey(t *testing.T) {
	guard := newHistoryResourceAdmission(1)
	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	if _, err := guard.acquire(ctx, "user-a\x00vehicle-a"); err == nil {
		t.Fatal("expected cancellation")
	}
	first, err := guard.acquire(context.Background(), "user-a\x00vehicle-a")
	if err != nil { t.Fatal(err) }
	defer first()
	if _, err := guard.acquire(context.Background(), "user-b\x00vehicle-b"); err != nil { t.Fatal(err) }
}
